kind: ConfigMap
metadata:
  name: {{ include "search-api.fullname" . }}-config
  labels:
    {{- include "search-api.labels" . | nindent 4 }}
data:
  # ===== 서비스 특화 설정 (공통 ConfigMap에 없는 것들) =====
  OTEL_SERVICE_NAME: {{ .Values.otelServiceName | quote }}
